  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Determines whether a booking request is valid based on business rules.
   * Algorithm:
   *   1. Validate inputs: customer, trip, and bookingDate must not be null.
   *   2. Validate trip times: departureTime and arrivalTime must be valid datetime strings in format yyyy-MM-dd HH:mm, and departureTime < arrivalTime.
   *   3. Validate numberOfSeats > 0 and <= trip.numberOfSeats (remaining available seats).
   *   4. Check booking time rule: the bookingDate must be strictly more than 2 hours before trip.departureTime (i.e., bookingDate + 2 hours < departureTime).
   *   5. Check overlap rule: ensure no other booking of this customer (excluding this one) exists whose trip time interval overlaps with this trip on the same calendar day.
   *      - Overlap condition: start1 < end2 and start2 < end1, where start = departureTime, end = arrivalTime.
   *      - Compare only trips on the same calendar day (based on departureTime date).
   *   6. If all checks pass, return true; otherwise return false.
   * Related Features: Booking.customer, Booking.trip, Booking.bookingDate, Booking.numberOfSeats, Trip.departureTime, Trip.arrivalTime, Trip.numberOfSeats, Customer.bookings
   * Related Classes: Customer, Trip, Booking
   * Input: None (uses internal fields: this.customer, this.trip, this.bookingDate, this.numberOfSeats)
   * Output: boolean - true if eligible, false otherwise
   * Pre-condition: None
   * Post-condition: None (no state change; only validation)
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    // Step 1: Validate inputs
    if (getCustomer() == null || getTrip() == null || getBookingDate() == null) {
      return false;
    }

    Trip currentTrip = getTrip();
    String departureTimeStr = currentTrip.getDepartureTime();
    String arrivalTimeStr = currentTrip.getArrivalTime();

    // Step 2: Validate trip times
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
    sdf.setLenient(false);
    
    Date departureTime;
    Date arrivalTime;
    try {
      departureTime = sdf.parse(departureTimeStr);
      arrivalTime = sdf.parse(arrivalTimeStr);
    } catch (ParseException e) {
      return false;
    }

    if (!departureTime.before(arrivalTime)) {
      return false;
    }

    // Step 3: Validate numberOfSeats
    int seatsToBook = getNumberOfSeats();
    if (seatsToBook <= 0 || seatsToBook > currentTrip.getNumberOfSeats()) {
      return false;
    }

    // Step 4: Check booking time rule (bookingDate + 2 hours < departureTime)
    Calendar cal = Calendar.getInstance();
    cal.setTime(getBookingDate());
    cal.add(Calendar.HOUR_OF_DAY, 2);
    Date bookingPlus2Hours = cal.getTime();
    
    if (!bookingPlus2Hours.before(departureTime)) {
      return false;
    }

    // Step 5: Check overlap rule
    // Get all bookings of this customer
    for (Booking otherBooking : getCustomer().getBookings()) {
      // Skip this booking itself
      if (otherBooking == this) {
        continue;
      }
      
      Trip otherTrip = otherBooking.getTrip();
      if (otherTrip == null) {
        continue;
      }
      
      String otherDepartureStr = otherTrip.getDepartureTime();
      String otherArrivalStr = otherTrip.getArrivalTime();
      
      try {
        Date otherDeparture = sdf.parse(otherDepartureStr);
        Date otherArrival = sdf.parse(otherArrivalStr);
        
        // Check if same calendar day
        Calendar cal1 = Calendar.getInstance();
        cal1.setTime(departureTime);
        Calendar cal2 = Calendar.getInstance();
        cal2.setTime(otherDeparture);
        
        if (cal1.get(Calendar.YEAR) == cal2.get(Calendar.YEAR) &&
            cal1.get(Calendar.DAY_OF_YEAR) == cal2.get(Calendar.DAY_OF_YEAR)) {
          
          // Overlap condition: start1 < end2 AND start2 < end1
          if (departureTime.before(otherArrival) && otherDeparture.before(arrivalTime)) {
            return false;
          }
        }
      } catch (ParseException e) {
        continue;
      }
    }

    // Step 6: All checks passed
    return true;
  }

